ObjectDesired(what=$,who=$)
{
   if Send(what,@CanBeGivenToNPC) and 
      (Send(Self,@IsObjectWearable,#what=what) OR
       Send(Self,@IsObjectWeapon,#what=what))
   {  
      return True;  
   }
   return False;
}

   ObjectDesired(what=$,who=$)
   {
      if IsClass(what,&NumberItem) and
         Send(what,@GetNumber) > 100
      {
         return FALSE;
      }

      if Send(self,@IsObjectGem,#what=what) or
         Send(self,@IsObjectSundry,#what=what)
      {
	      return TRUE;
      }

      return FALSE;
   }

   ObjectDesired(what=$,who=$,report=TRUE)
   "This is set in individual buyers.  It allows them to pick and choose"
   "what they want to buy."
   {
      local i;

      % Don't take money for resale.  That's just silly.
      if IsClass(what,&Money)
      {
         return FALSE;
      }

      if length(first(plFor_Sale)) > MAX_FORSALE
      {
         Send(self,@SayToOne,#target=who,#message_rsc=JunkMan_Full_rsc);
		 return FALSE;
      }

      for i in first(plFor_Sale)
      {
         if GetClass(i) = GetClass(what)
         {
            if IsClass(i,&NumberItem)
            {
			   % Only accept stackable items if we don't have too many of them.
               if (send(what,@GetNumber) + send(i,@GetNumber)) < NUMBER_ITEM_MAX
			   {
			      return TRUE;
			   }
			   Send(self,@SayToOne,#target=who,#message_rsc=JunkMan_too_many_rsc);
            }
			else
			{
			   Send(self,@SayToOne,#target=who,#message_rsc=JunkMan_AlreadyHaveOne_rsc);
			}

            return FALSE;
         }
      }

      if send(what,@HasAttribute,#ItemAtt=IA_BONDED) OR send(what,@IsItemType,#type=ITEMTYPE_SPECIAL)
      {
         return FALSE;
      }

      if IsClass(what,&Token) OR IsClass(what,&Totem)
      {
         return FALSE;
      }
      
      return TRUE;
   }

